style.css:
@-moz-document domain("youtube.com") {
/* fond simple */
    body {
        background: #fff7d6 !important;
        color: #333 !important;
    }

    /* remplacer logo */
    #logo-icon {
        content: url("https://i.pinimg.com/736x/af/7f/ad/af7fad111a2c880fe70ac7e39aceb5d3.jpg") !important;
        width: 36px !important;
        height: 36px !important;
    }

    /* cacher logo original */
    ytd-topbar-logo-renderer svg {
        display: none !important;
    }

    /* thumbnails clean */
    ytd-thumbnail img {
        border-radius: 10px !important;
    }

    /* boutons simples */
    button {
        border-radius: 8px !important;
    }
}
